('La Oficina Central de Admisión (OCA) atiende de lunes a viernes de 9:00 a 16:00 y gestiona todos los procesos de admisión de la UNMSM: examen ordinario, traslado interno y externo, ingreso directo para egresados y la modalidad PIR, entre otros. La universidad realiza dos exámenes de admisión al año, aproximadamente en marzo y septiembre.', '{"title": "Oficina Central de Admisión (OCA)", "place_id": "oca", "position": 0, "document_id": "doc-oca"}'::jsonb, '[-0.00087015994,0.0024797411,0.046494994,-0.09490026,0.026959386,0.041246686,0.0029306307,0.024075266,-0.006918328,-0.019656062,-0.02448601,-0.012050579,-0.034461524,0.019217392,0.16675611,0.05494235,-0.011455102,0.008829085,0.0075187115,-0.05343161,-0.016341547,-0.029673848,-0.008622171,-0.0015500803,-0.031372156,0.032919172,0.042777397,-0.027000349,0.026624661,0.0028589224,-0.051531382,0.044348136,-0.035492998,-0.02433861,-0.017901596,-0.016523842,0.0031059273,0.011633426,-0.025186324,-0.016178798,0.038196847,-0.003891739,-0.0057471874,0.014920827,0.007156443,-0.0407894,-0.039891344,-0.1099233,-0.03949835,-0.021543633,-0.021297915,0.02520768,0.0025881247,-0.3174168,-0.008795328,-0.009124557,0.013785293,-0.008008362,-0.0021389895,-0.036824614,-0.09819073,0.03926341,-0.037384022,-0.0045056483,0.00024831732,-0.02905961,0.014796064,0.07578552,-0.02649468,-0.0075308774,0.019082418,-0.03984824,0.036540948,-0.0076927887,0.0013136868,-0.0105757695,-0.00042207804,0.01947651,-0.017954545,0.010706765,-0.0050987923,0.011120486,0.023976305,-0.0012542998,0.011950674,-0.012252307,0.023959206,-0.012396687,-0.011460851,0.011423185,-0.0066274246,0.030330041,0.016576538,-0.08199553,0.05974492,0.01681998,-0.020594021,-0.02512942,-0.026510488,-0.04283139,-0.0095356535,-0.004604133,-0.006828839,0.020029087,0.04531001,-0.093942046,0.012820542,-0.032833643,-0.0004524256,0.012638958,-0.023105308,0.029627472,0.0034413438,-0.021738425,0.011869247,-0.30420592,-0.0075632473,-0.0053436775,-0.019785777,-0.018001344,0.01593333,0.047382638,-0.