('La Facultad de Letras y Ciencias Humanas (FLCH) está en el patio central histórico del campus y ofrece carreras como Literatura, Lingüística, Filosofía, Historia, Arte, Comunicación Social, Bibliotecología y Traducción e Interpretación. Es la única del Perú con Conservación y Restauración y cuenta con tres auditorios, biblioteca especializada y Centro de Idiomas.', '{"title": "Facultad de Letras y Ciencias Humanas (FLCH)", "place_id": "letras-humanidades", "position": 0, "document_id": "doc-letras"}'::jsonb, '[0.03750229,-0.014669079,0.060317203,-0.08312773,0.012050557,0.007829004,-0.011328736,0.05031335,0.009011034,0.0046117455,-0.014459171,0.015285487,-0.029473506,0.03983204,0.16024473,0.02735401,0.00064797956,-0.02450164,0.0026992757,-0.020526322,0.019300971,-0.017054271,-0.038555846,0.023170698,-0.04825809,0.006097381,-0.00092860294,0.0001747342,-0.0113804,-0.036039036,-0.012890389,0.08495705,0.015774935,-0.032904424,0.009121888,0.015735129,0.010377845,-0.012630111,-0.032138243,0.02610904,0.021238264,0.066015825,0.0018525983,-0.0034517772,0.061758295,-0.027716316,-0.016352404,-0.05320337,0.0005737047,-0.0016933669,0.010051092,0.023235934,0.0079035,-0.33081353,-0.01651557,-0.006079792,-0.008400021,0.012005842,-0.0002693883,-0.01606258,-0.046188768,0.028453063,-0.041078687,0.022969032,0.021085102,0.050260648,0.0021146801,0.0829493,0.0044387947,-0.0064575938,-0.020068841,-0.0036840565,0.04104872,-0.0159151,0.00017623437,-0.0037100862,-0.03087131,-0.0037857275,0.016967589,0.04970907,-0.009388837,0.045004617,-0.016462438,-0.03440564,0.03656744,-0.014334645,0.012878962,0.027774803,-0.0063119554,0.006203662,-0.0018445399,0.020983139,-0.028078685,-0.024214152,0.06075961,0.0023851437,-0.012857938,-0.0370198,-0.024136098,-0.028742185,-0.021993222,-0.0033198625,0.018495154,0.048408777,0.0082829865,-0.04430285,0.051829126,-0.007127462,-0.0056694834,0.029598372,-0.014289398,0.012890919,-0.044202548,0.00010724989,0.06742237,-0.30853742,0.05730445,-0.025372844,-0.05895979,0.